  $$('[data-quote-field]').forEach(el=>{const k=el.dataset.quoteField;if(document.activeElement===el)return;if(el.type==="checkbox")el.checked=!!q[k];else el.value=q[k]??"";});
  const st=$("#tcQuoteStatus");if(st){st.textContent=q.status||"Not Generated";st.className=`tc-quote-status ${quotationStatusClass(q.status)}`;}if($("#tcQuoteRef"))$("#tcQuoteRef").textContent=q.quoteNo||"Not generated";if($("#tcQuotePrice"))$("#tcQuotePrice").textContent=money(q.totalAmount||sum.finalSale,cur);if($("#tcQuoteLinked"))$("#tcQuoteLinked").textContent=c.inquiryRef?`Linked Inquiry: ${c.inquiryRef}`:"No linked inquiry — preview/print only";if($("#tcSendQuoteBtn"))$("#tcSendQuoteBtn").disabled=!c.inquiryRef;if($("#tcConvertBookingBtn"))$("#tcConvertBookingBtn").disabled=!c.inquiryRef||q.status==="Booked";$("#tcQuotePreview").innerHTML=quotationPreviewHtml();
