  const stepTabs=$('.tc-step-tabs'), actualTab=stepTabs?.querySelector('[data-step="actual"]');if(actualTab&&!stepTabs.querySelector('[data-step="operations"]'))actualTab.insertAdjacentHTML('afterend','<button data-step="operations" type="button">10 Operations / Voucher</button>');
  const actualPane=$('[data-step-pane="actual"]');if(actualPane&&!$('[data-step-pane="operations"]'))actualPane.insertAdjacentHTML('afterend',`<div class="tc-step" id="tcOperationsPane" data-step-pane="operations"><div class="tc-section-title"><div><span>STEP 10</span><h3>Tour Operations &amp; Service Voucher</h3><p>Turn the booked costing into an operational checklist, supplier confirmation register and printable guest voucher.</p></div><div class="tc-quote-head-actions"><span id="tcOperationsStatus" class="tc-quote-status warn">Planning</span><span id="tcOperationsCount" class="tc-op-count">0/0 services confirmed</span></div></div><div class="tc-form-grid four"><label>Operations Status<select data-operations-field="status"><option>Planning</option><option>In Progress</option><option>Ready</option><option>Completed</option></select></label><label>Pickup Location<input data-operations-field="pickupLocation" placeholder="Airport / hotel / address"></label><label>Pickup Time<input data-operations-field="pickupTime" type="time"></label><label>Arrival Flight No.<input data-operations-field="flightNo" placeholder="UL / WY / EK..."></label><label>Arrival Time<input data-operations-field="arrivalTime" type="datetime-local"></label><label>Drop Location<input data-operations-field="dropLocation" placeholder="Airport / hotel / address"></label><label>Drop Time<input data-operations-field="dropTime" type="time"></label><label>Departure Flight No.<input data-operations-field="departureFlightNo" placeholder="UL / WY / EK..."></label><label>Departure Time<input data-operations-field="departureTime" type="datetime-local"></label><label>Driver Name<input data-operations-field="driverName" list="tcOpsDriverResources"></label><label>Driver Mobile<input data-operations-field="driverMobile"></label><label>Guide Name<input data-operations-field="guideName" list="tcOpsGuideResources"></label><label>Guide Mobile<input data-operations-field="guideMobile"></label><label>Vehicle / Type<input data-operations-field="vehicleName" list="tcOpsVehicleResources"></label><label>Vehicle No.<input data-operations-field="vehicleNo" placeholder="Registration / fleet no."></label><label>Emergency Contact<input data-operations-field="emergencyContact"></label></div><datalist id="tcOpsDriverResources"></datalist><datalist id="tcOpsGuideResources"></datalist><datalist id="tcOpsVehicleResources"></datalist><div id="tcOpsConflictInline" class="tc-op-conflict-inline hidden"></div><div class="tc-operations-actions"><button class="tc-btn ghost" id="tcSyncOperationsBtn" type="button">Sync from Costing</button><button class="tc-btn ghost" id="tcPrintOpsBtn" type="button">Print Operations Sheet</button><button class="tc-btn ghost" id="tcPrintVoucherBtn" type="button">Print Guest Voucher</button><button class="tc-btn tc-book-btn" id="tcOpsReadyBtn" type="button">Mark Ready</button></div><div class="tc-section-title compact"><div><h3>Service Confirmations</h3><p>Hotels, transport, activities and staff are generated from the costing. Record supplier confirmation references before travel.</p></div></div><div class="tc-line-table-wrap"><table class="tc-line-table tc-operations-table"><thead><tr><th>Day</th><th>Type</th><th>Supplier</th><th>Service</th><th>Status</th><th>Confirmation Ref</th><th>Contact</th><th>Notes</th></tr></thead><tbody id="tcOperationsBody"></tbody></table></div><label class="tc-full">Internal Operations Notes<textarea data-operations-field="internalNotes" rows="4" placeholder="Special arrangements, emergency notes, rooming notes, driver instructions…"></textarea></label><div class="tc-operations-actions final"><button class="tc-btn" id="tcSaveOperationsBtn" type="button">Save Operations</button></div></div>`);
