function financeDocumentDefaults(c=state.current){
  const d=c?.documents||{},q=c?.quotation||{},sum=computeSummary(c||blankCosting()),base=String(c?.inquiryRef||c?.reference||`TC-${Date.now()}`).replace(/[^A-Za-z0-9-]/g,"");
  const inv={...(d.invoice||{})};
  inv.invoiceNo=inv.invoiceNo||`INV-${base}`; inv.issueDate=inv.issueDate||today(); inv.dueDate=inv.dueDate||dateAdd(today(),7); inv.status=inv.status||"Draft";
  inv.customerName=inv.customerName||q.guestName||c?.guestName||""; inv.customerEmail=inv.customerEmail||q.guestEmail||c?.guestEmail||""; inv.customerAddress=inv.customerAddress||"";
  if(inv.amount===""||inv.amount==null)inv.amount=num(q.totalAmount||sum.finalSale); if(inv.paidAmount===""||inv.paidAmount==null)inv.paidAmount=0;
  inv.paymentTerms=inv.paymentTerms||q.paymentTerms||"Payment is due as per the confirmed tour booking terms."; inv.notes=inv.notes||"";
  return {invoice:inv,receipts:asArray(d.receipts),supplierPOs:asArray(d.supplierPOs)};
}
function ensureFinancialDocuments(){if(!state.current)return null;state.current.documents=financeDocumentDefaults(state.current);return state.current.documents;}
function financeTotals(){const d=ensureFinancialDocuments()||{invoice:{},receipts:[]},invoice=num(d.invoice.amount),receiptTotal=d.receipts.reduce((s,r)=>s+num(r.amount),0),manualPaid=num(d.invoice.paidAmount),paid=Math.max(manualPaid,receiptTotal),balance=Math.max(0,invoice-paid);return {invoice:round2(invoice),receiptTotal:round2(receiptTotal),paid:round2(paid),balance:round2(balance)};}
function syncInvoiceFromCosting(silent=false){if(!state.current)return;const d=ensureFinancialDocuments(),q=ensureQuotation(),sum=computeSummary();d.invoice.invoiceNo=d.invoice.invoiceNo||`INV-${String(state.current.inquiryRef||state.current.reference||Date.now()).replace(/[^A-Za-z0-9-]/g,"")}`;d.invoice.issueDate=d.invoice.issueDate||today();d.invoice.dueDate=d.invoice.dueDate||dateAdd(today(),7);d.invoice.customerName=q.guestName||state.current.guestName||d.invoice.customerName;d.invoice.customerEmail=q.guestEmail||state.current.guestEmail||d.invoice.customerEmail;d.invoice.amount=num(q.totalAmount||sum.finalSale);d.invoice.paymentTerms=q.paymentTerms||d.invoice.paymentTerms;renderFinancialDocuments();setDirty();if(!silent)toast("Invoice refreshed from current costing / quotation");}
