async function uploadTourDocument(){
  if(!state.current)return;const input=$("#tcDocumentUpload"),file=input?.files?.[0];if(!file){toast("Choose a document first",true);return;}
  if(!state.current.id){await saveCurrent();if(!state.current?.id){toast("Save the costing before uploading documents",true);return;}}
  const btn=$("#tcUploadDocumentBtn");if(btn){btn.disabled=true;btn.textContent="Uploading…";}
  try{const fd=new FormData();fd.append("file",file);fd.append("reference",state.current.reference||state.current.id);fd.append("category",$("#tcDocumentCategory")?.value||"Other");fd.append("linkedTo",$("#tcDocumentLinkedTo")?.value||"");const res=await api("/api/admin/finance/tour-documents/upload",{method:"POST",body:fd});const dc=ensureDocumentCenter();dc.files.push({id:uid("doc"),category:$("#tcDocumentCategory")?.value||"Other",linkedTo:$("#tcDocumentLinkedTo")?.value||"",fileName:res.fileName||file.name,storageKey:res.storageKey||"",contentType:res.contentType||file.type||"application/octet-stream",size:num(res.size||file.size),uploadedAt:res.uploadedAt||new Date().toISOString(),expiryDate:$("#tcDocumentExpiry")?.value||"",status:"Received",notes:$("#tcDocumentUploadNotes")?.value||""});input.value="";$("#tcDocumentLinkedTo").value="";$("#tcDocumentExpiry").value="";$("#tcDocumentUploadNotes").value="";setDirty();renderDocumentCenter();await saveCurrent();setStep("documentCenter");toast("Document uploaded securely and linked to this tour");}catch(e){toast(e.message||"Document upload failed",true);}finally{if(btn){btn.disabled=false;btn.textContent="Upload Secure Document";}}
}
async function openTourDocument(index,download=false){
  const r=ensureDocumentCenter()?.files?.[index];if(!r?.storageKey)return toast("Secure file reference is missing",true);
  const viewer=download?null:window.open("about:blank","_blank");try{const res=await fetch(`${API_BASE}/api/admin/finance/tour-documents/file?key=${encodeURIComponent(r.storageKey)}&download=${download?"1":"0"}`,{headers:authHeaders(false)});if(!res.ok){let m=`Request failed (${res.status})`;try{const j=await res.json();m=j.error||m;}catch(_){}throw new Error(m);}const blob=await res.blob(),url=URL.createObjectURL(blob);if(download){const a=document.createElement("a");a.href=url;a.download=r.fileName||"tour-document";document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}else if(viewer){viewer.location.href=url;setTimeout(()=>URL.revokeObjectURL(url),60000);}else{toast("Allow pop-ups to view the document",true);}}catch(e){if(viewer)try{viewer.close()}catch(_){}toast(e.message||"Could not open document",true);}
}
