function ocOverlap(a,b){const a1=ocDate(a.travelStart),a2=ocEndDate(a),b1=ocDate(b.travelStart),b2=ocEndDate(b);return !!(a1&&a2&&b1&&b2&&a1<=b2&&b1<=a2);}
