function ocDocFlags(c){const files=asArray(c?.documentCenter?.files).filter(x=>x.status!=="Rejected"),cats=new Set(files.map(x=>normalizeKey(x.category)));return {passport:cats.has("passport"),visa:cats.has("visa"),ticket:cats.has("air ticket")};}
