  asArray(c.activities).forEach((r,i)=>{const n=parseInt(String(r.day||"").match(/\d+/)?.[0]||String(i+1),10)||i+1;if(date===dateAdd(start,n-1))out.push({type:"Activity",text:r.activity||"Activity"});});
  if(date===end){if(o.dropLocation||o.dropTime)out.push({type:"Drop",text:`${o.dropLocation||"Drop"}${o.dropTime?` · ${o.dropTime}`:""}`});if(o.departureTime||o.departureFlightNo)out.push({type:"Departure",text:`${o.departureFlightNo||"Flight"}${o.departureTime?` · ${String(o.departureTime).replace("T"," ")}`:""}`});}
